// Agent output is in items[0].json.output
const raw = items[0].json.output || '';

// Strip any accidental markdown fences the LLM may add
const cleaned = raw
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // If JSON parse fails, return an error payload for the error branch
  return [{ json: { parse_error: true, raw_output: raw, error: e.message } }];
}

// Determine output type
let output_type = 'UNKNOWN';
if (parsed.action === 'NO_ACTION')         output_type = 'NO_ACTION';
else if (parsed.risk_id)                   output_type = 'RISK';
else if (parsed.sprint_id)                 output_type = 'VELOCITY';
else if (parsed.id && parsed.id.startsWith('SH-')) output_type = 'STAKEHOLDER';

return [{ json: { ...parsed, _output_type: output_type, _parsed_at: new Date().toISOString() } }];

// Read existing register, upsert the new/updated risk entry
const fs = require('fs');
const path = '/home/node/artifacts/risk_register.json';
const existing = JSON.parse(fs.readFileSync(path, 'utf8'));
const newRisk = items[0].json;

// Remove internal agent fields
delete newRisk._output_type;
delete newRisk._parsed_at;

const idx = existing.risks.findIndex(r => r.risk_id === newRisk.risk_id);
if (idx >= 0) {
  existing.risks[idx] = { ...existing.risks[idx], ...newRisk };
} else {
  existing.risks.push(newRisk);
}
existing.last_updated = new Date().toISOString().split('T')[0];

fs.writeFileSync(path, JSON.stringify(existing, null, 2));
return [{ json: { success: true, action: idx >= 0 ? 'updated' : 'created', risk_id: newRisk.risk_id } }];

const fs = require('fs');
const path = '/home/node/artifacts/velocity_log.json';
const existing = JSON.parse(fs.readFileSync(path, 'utf8'));
const newSprint = items[0].json;

delete newSprint._output_type;
delete newSprint._parsed_at;

const idx = existing.sprints.findIndex(s => s.sprint_id === newSprint.sprint_id);
if (idx >= 0) {
  existing.sprints[idx] = { ...existing.sprints[idx], ...newSprint };
} else {
  existing.sprints.push(newSprint);
}
existing.last_updated = new Date().toISOString().split('T')[0];

fs.writeFileSync(path, JSON.stringify(existing, null, 2));
return [{ json: { success: true, sprint_id: newSprint.sprint_id } }];

const fs = require('fs');
const path = '/home/node/artifacts/stakeholder_map.json';
const existing = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path, 'utf8')) : { project_id: 'PROJ-001', version: '1.0', last_updated: '', stakeholders: [] };
const newSH = items[0].json;

delete newSH._output_type;
delete newSH._parsed_at;

const idx = existing.stakeholders.findIndex(s => s.id === newSH.id);
if (idx >= 0) {
  existing.stakeholders[idx] = { ...existing.stakeholders[idx], ...newSH };
} else {
  existing.stakeholders.push(newSH);
}
existing.last_updated = new Date().toISOString().split('T')[0];

fs.writeFileSync(path, JSON.stringify(existing, null, 2));
return [{ json: { success: true, stakeholder_id: newSH.id } }];

const fs = require('fs');
const entry = { timestamp: new Date().toISOString(), ...items[0].json };
const logPath = '/home/node/artifacts/no_action.log.jsonl';
fs.appendFileSync(logPath, JSON.stringify(entry) + '\n');
return [{ json: { logged: true, ...entry } }];

const fs = require('fs');
const error = { timestamp: new Date().toISOString(), node: $input.item?.pairedItem?.node || 'unknown', error: items[0].json };
fs.appendFileSync('/home/node/logs/pipeline_errors.jsonl', JSON.stringify(error) + '\n');
console.error('Pipeline error:', JSON.stringify(error));
return [{ json: error }];
